const BOOTSTRAP_KEYS = new Set(BOOTSTRAP.map(entry => entry.key));
const RPC_PATHS = new Set(RPCS.map(entry => entry.path));
const API_ORIGIN = 'https://api.worldmonitor.app';

const byGroup = (entries, line) => GROUPS
  .map(group => [group, entries.filter(entry => entry.group === group)])
  .filter(([, members]) => members.length)
  .map(([group, members]) => `${group}:\n${members.map(line).join('\n')}`)
  .join('\n\n');

const WIDGET_DATA_CATALOG = `## Option 1 — Bootstrap (pre-seeded, instant, matches dashboard panels exactly)
Use: /api/bootstrap?keys=<key> (comma-separate several keys) — response shape: { data: { <key>: <array or object> } }
PREFER this over RPCs whenever a key matches the user's topic.
Quote keys (marketQuotes, commodityQuotes, cryptoQuotes, gulfQuotes) hold the current price, change % and a sparkline of recent prices with no dates; its interval varies by source (today's intraday ticks or the last few daily closes), so it is not a dated history. Add params.symbols (comma-separated) to return only those quotes. commodityQuotes symbols: GC=F gold, SI=F silver, HG=F copper, PL=F platinum, PA=F palladium, CL=F WTI, BZ=F Brent, NG=F natural gas, TTF=F EU gas, ZW=F wheat, ZC=F corn, KC=F coffee, plus FX pairs such as EURUSD=X and USDJPY=X.

${byGroup(BOOTSTRAP, entry => `- ${entry.key}: ${entry.holds}`)}

## Option 2 — Data RPCs (use when no bootstrap key matches or you need a parameter)
GET these paths; pass parameters in params.
${byGroup(RPCS, entry => `- ${entry.path}${entry.params ? ` (${entry.params})` : ''}: ${entry.holds}`)}
`;

function approvedBootstrapQuery(searchParams, requireKeys) {
  if ([...searchParams.keys()].some(key => key !== 'keys' && key !== 'public')) return false;
  const markers = searchParams.getAll('public');
  if (markers.length > 1 || (markers.length === 1 && markers[0] !== '1')) return false;
  const values = searchParams.getAll('keys');
  if (!values.length) return !requireKeys;
  const keys = values[0].split(',');
  return values.length === 1
    && (!markers.length || keys.length === 1)
    && new Set(keys).size === keys.length
    && keys.every(key => BOOTSTRAP_KEYS.has(key));
}

// Validate both supplied queries and the final URL. Never let URL normalization
// turn a denied spelling into an approved path, or params hide a denied key.
function buildWidgetDataUrl(endpoint, params = {}) {
  if (typeof endpoint !== 'string' || !endpoint.startsWith('/api/')
      || /[\\#\s\u0000-\u001f\u007f]/u.test(endpoint)
      || /%(?![0-9a-f]{2})/i.test(endpoint)
      || !params || typeof params !== 'object' || Array.isArray(params)) return null;
  const rawPath = endpoint.split('?')[0];
  if (rawPath !== '/api/bootstrap' && !RPC_PATHS.has(rawPath)) return null;
  const entries = Object.entries(params);
  if (entries.some(([, value]) => !['string', 'number', 'boolean'].includes(typeof value))) return null;
  const query = entries.map(([key, value]) => [key, String(value)]);

  const url = new URL(endpoint, API_ORIGIN);
  if (url.origin !== API_ORIGIN || url.pathname !== rawPath || url.username || url.password || url.hash) return null;
  if (rawPath === '/api/bootstrap'
      && (!approvedBootstrapQuery(url.searchParams, false)
          || !approvedBootstrapQuery(new URLSearchParams(query), false))) return null;
  for (const [key, value] of query) url.searchParams.set(key, value);
  if (url.origin !== API_ORIGIN || url.pathname !== rawPath
      || (rawPath === '/api/bootstrap' && !approvedBootstrapQuery(url.searchParams, true))) return null;
  return url;
}

module.exports = {
  WIDGET_DATA_CATALOG, buildWidgetDataUrl,
  BOOTSTRAP, RPCS, EXCLUDED_BOOTSTRAP_KEYS, EXCLUDED_RPC_ROUTES,
};
